import type { SelectProps } from "@components/select";

import { Select } from "@components/select";
import React from "react";

import { useMainNav } from "../hooks/use-main-nav";

export const MainNavSelect: React.FC<React.PropsWithChildren> = ({ children }) => {
  const { collapsed, theme } = useMainNav();

  const selectChild = React.Children.only(children);

  if (!React.isValidElement(selectChild) || selectChild.type !== Select) {
    return null;
  }

  const clonedSelect = React.cloneElement(selectChild as React.ReactElement<SelectProps>, {
    ...selectChild.props,
    collisionPadding: 0,
    "data-main-nav-state": collapsed ? "collapsed" : "expanded",
    side: "right",
    sideOffset: collapsed ? theme.toPx("0.86rem") : theme.toPx("1.14rem"),
  });

  return clonedSelect;
};
MainNavSelect.displayName = "MainNav.Select";
